Object.assign(STRINGS.de, { qr_sheet: 'QR-Aufkleber drucken', qr_sticker: 'QR-Aufkleber', qr_sheet_hint: 'Aufkleber z. B. innen an die Fahrertür kleben. Scannen öffnet für dieses Fahrzeug „Schaden melden“ oder „Abfahrtskontrolle“ – Anmeldung ist weiterhin nötig, der Code enthält keine Zugangsdaten.', qr_sticker_text: 'Schaden? Hier scannen und melden.', qr_sticker_sub: 'Пошкодження? Скануйте · Damage? Scan to report', qr_vehicle_unknown: 'Fahrzeug aus dem QR-Code nicht gefunden – bitte auswählen.' });
