Object.assign(STRINGS.de, { kpi_locked: 'gesperrt' });
Object.assign(STRINGS.uk, { kpi_locked: 'заблоковано' });
Object.assign(STRINGS.en, { kpi_locked: 'locked' });
Object.assign(STRINGS.de, { days_one: 'Tag', days_other: 'Tage', kpi_downtime: 'Ausfall', vd_title: 'Ausfall je Monat (letzte {n})', vd_total: 'Summe', vd_rule: 'Werkstatt-Übernahme bis Freigabe (offene Aufträge bis jetzt) und Zeit mit Sicherheitssperre zusammen; mehrere Aufträge gleichzeitig zählen einmal. Verfügbarkeit = Anteil der Stunden des Monats ohne Ausfall (ab Anlage des Fahrzeugs in der App, laufender Monat bis jetzt). Nur gespeicherte Zeitpunkte, nichts geschätzt.' });
Object.assign(STRINGS.uk, { days_one: 'день', days_few: 'дні', days_many: 'днів', days_other: 'дня', kpi_downtime: 'Простій', vd_title: 'Простій за місяцями (останні {n})', vd_total: 'Разом', vd_rule: 'Від прийняття майстернею до допуску (відкриті замовлення – до зараз) разом із часом блокування безпеки; кілька замовлень одночасно рахуються один раз. Готовність = частка годин місяця без простою (від внесення транспорту в застосунок, поточний місяць – до зараз). Лише збережені часові мітки, без оцінок.' });
Object.assign(STRINGS.en, { days_one: 'day', days_other: 'days', kpi_downtime: 'Downtime', vd_title: 'Downtime per month (last {n})', vd_total: 'Total', vd_rule: 'Workshop takeover until release (open orders until now) plus time with safety lock; several orders at the same time count once. Availability = share of the month’s hours without downtime (from when the vehicle was added to the app, current month until now). Stored timestamps only, nothing estimated.' });
Object.assign(STRINGS.de, { vm_title: 'Fahrleistung je Monat (letzte {n})', vm_since: 'seit Ablesung vom {d}', vm_decrease: 'Rückgang des km-Stands – kein Wert', vm_first: 'erste Ablesung', vm_total: 'Summe der Monate mit Wert', vm_last: 'Letzter km-Stand', vm_rule: 'km des Monats = letzte Ablesung im Monat minus letzte Ablesung davor. Liegt die vorherige Ablesung vor dem Vormonat, umfasst der Wert mehrere Monate („seit Ablesung vom …“). Monate ohne Ablesung fehlen; bei einem Rückgang (z. B. Tachotausch) gibt es keinen Wert. Nur gespeicherte km-Stände, nichts geschätzt.' });
Object.assign(STRINGS.uk, { vm_title: 'Пробіг за місяць (останні {n})', vm_since: 'від показника за {d}', vm_decrease: 'Зменшення показника км – без значення', vm_first: 'перший показник', vm_total: 'Сума місяців зі значенням', vm_last: 'Останній показник км', vm_rule: 'Км за місяць = останній показник у місяці мінус останній показник перед ним. Якщо попередній показник раніше за попередній місяць, значення охоплює кілька місяців («від показника за …»). Місяці без показника не наведено; у разі зменшення (напр. заміна тахографа) значення немає. Лише збережені показники км, без оцінок.' });
Object.assign(STRINGS.en, { vm_title: 'Mileage per month (last {n})', vm_since: 'since reading of {d}', vm_decrease: 'Odometer went down – no value', vm_first: 'first reading', vm_total: 'Total of months with a value', vm_last: 'Latest odometer reading', vm_rule: 'km of the month = last reading in the month minus the last reading before it. If that previous reading is older than the previous month, the value covers several months (“since reading of …”). Months without a reading are not shown; if the odometer went down (e.g. tachograph replaced) there is no value. Stored odometer readings only, nothing estimated.' });
Object.assign(STRINGS.de, { kpi_av: 'Technische Verfügbarkeit', kpi_av_short: 'Verfügbarkeit', kpi_av_of: 'der Fahrzeugstunden verfügbar', kpi_av_line: 'Fahrzeuge: {n} · Ausfall gesamt: {d}', kpi_av_lowest: 'Geringste Verfügbarkeit im Zeitraum', kpi_av_none: 'Im Zeitraum kein Ausfall erfasst.', kpi_av_rule: 'Ausfall = Werkstatt-Übernahme bis technische Freigabe bzw. Ablehnung (offen bis jetzt) und Zeit mit Sicherheitssperre, je Fahrzeug Überschneidungen einmal, auf den Zeitraum zugeschnitten (auch Vorgänge aus früheren Monaten). Fahrzeugstunden = aktive Fahrzeuge laut Stamm (ohne ruhende) vom Monatsbeginn bzw. ihrer Anlage bis Monatsende bzw. jetzt. Werkstattaufenthalte ohne Vorgang in der App sind nicht erfasst – die Quote ist daher eine Obergrenze.', kpi_av_site: 'Mit Werkstattfilter wird keine Verfügbarkeit berechnet – sie gilt für das ganze Fahrzeug, nicht für eine Werkstatt.' });
Object.assign(STRINGS.uk, { kpi_av: 'Технічна готовність', kpi_av_short: 'Готовність', kpi_av_of: 'транспорто-годин доступно', kpi_av_line: 'Транспорт: {n} · Простій загалом: {d}', kpi_av_lowest: 'Найнижча готовність за період', kpi_av_none: 'За період простою не зафіксовано.', kpi_av_rule: 'Простій = від прийняття майстернею до технічного допуску або відхилення (відкриті – до зараз) і час із блокуванням безпеки; для кожного транспорту перекриття враховуються один раз, обрізано до періоду (також заявки з попередніх місяців). Транспорто-години = активний транспорт за довідником (без законсервованого) від початку місяця або дати внесення до кінця місяця або до зараз. Перебування в майстерні без заявки в застосунку не враховані – тому показник є верхньою межею.', kpi_av_site: 'З фільтром майстерні готовність не розраховується – вона стосується всього транспорту, а не майстерні.' });
Object.assign(STRINGS.en, { kpi_av: 'Technical availability', kpi_av_short: 'Availability', kpi_av_of: 'of vehicle hours available', kpi_av_line: 'Vehicles: {n} · Total downtime: {d}', kpi_av_lowest: 'Lowest availability in the period', kpi_av_none: 'No downtime recorded in the period.', kpi_av_rule: 'Downtime = workshop takeover until technical release or rejection (open until now) plus time under safety lock, overlaps counted once per vehicle, clipped to the period (including cases from earlier months). Vehicle hours = active vehicles in the master data (excluding dormant ones) from the start of the month or when they were added until the end of the month or now. Workshop stays without a case in the app are not recorded – the figure is therefore an upper bound.', kpi_av_site: 'With a workshop filter no availability is calculated – it applies to the whole vehicle, not to one workshop.' });
// [CLAUDE] Hinweise: Push-Zustand lesbar
Object.assign(STRINGS.de, { push_dev_n: 'Push: {n} Gerät(e)', push_dev_none: 'kein Push-Gerät', push_admin_hint: '{n} aktive(s) Konto/Konten im Betrieb ohne Push-Gerät – dringende Hinweise (z. B. Fahrzeugsperre) erreichen diese Personen nur, wenn sie die App öffnen. Empfehlung: bei der Einführung Push auf dem Handy einschalten lassen.', quiet_short: 'nur dringende Pushs', pst_held_opened: 'zurückgehalten (Ruhezeit) – in der App geöffnet', pst_held: 'zurückgehalten (Ruhezeit) bis {t}', quiet_title: 'Ruhezeit (keine nicht dringenden Pushs)', quiet_hint: 'In dieser Zeit kommen nur dringende Pushs (kritisch, nicht fahrbereit, Sperre). Alle anderen Hinweise stehen sofort hier in der App; der Push folgt gesammelt nach dem Ende der Ruhezeit. Uhrzeit Deutschland, auch über Mitternacht (z. B. 22:00–06:00).', quiet_from: 'von', quiet_to: 'bis', quiet_save: 'Ruhezeit speichern', quiet_off: 'Ruhezeit ausschalten', quiet_on: 'Ruhezeit {f}–{t}', quiet_none: 'Keine Ruhezeit eingestellt.' });
Object.assign(STRINGS.uk, { push_dev_n: 'Push: пристроїв {n}', push_dev_none: 'немає push-пристрою', push_admin_hint: 'Активних робочих акаунтів без push-пристрою: {n} – термінові сповіщення (напр. блокування транспорту) ці особи побачать лише відкривши застосунок. Рекомендація: під час запуску увімкнути push на телефоні.', quiet_short: 'лише термінові push', pst_held_opened: 'відкладено (час тиші) – відкрито в застосунку', pst_held: 'відкладено (час тиші) до {t}', quiet_title: 'Час тиші (без нетермінових push)', quiet_hint: 'У цей час надходять лише термінові push (критично, не на ходу, блокування). Усі інші сповіщення одразу видно тут у застосунку; push надійде разом після закінчення часу тиші. Час Німеччини, також через північ (напр. 22:00–06:00).', quiet_from: 'з', quiet_to: 'до', quiet_save: 'Зберегти час тиші', quiet_off: 'Вимкнути час тиші', quiet_on: 'Час тиші {f}–{t}', quiet_none: 'Час тиші не встановлено.' });
Object.assign(STRINGS.en, { push_dev_n: 'Push: {n} device(s)', push_dev_none: 'no push device', push_admin_hint: '{n} active production account(s) without a push device – urgent notifications (e.g. vehicle lock) only reach these people when they open the app. Recommendation: have push turned on on their phone during rollout.', quiet_short: 'urgent pushes only', pst_held_opened: 'held (quiet hours) – opened in the app', pst_held: 'held (quiet hours) until {t}', quiet_title: 'Quiet hours (no non-urgent pushes)', quiet_hint: 'During this time only urgent pushes arrive (critical, not roadworthy, lock). All other notifications appear here in the app straight away; the push follows as one summary after quiet hours end. German time, also across midnight (e.g. 22:00–06:00).', quiet_from: 'from', quiet_to: 'to', quiet_save: 'Save quiet hours', quiet_off: 'Turn off quiet hours', quiet_on: 'Quiet hours {f}–{t}', quiet_none: 'No quiet hours set.' });
