Object.assign(STRINGS.de, { ct_import: 'Verträge importieren (CSV)', ct_import_hint: 'Spalten: Kennzeichen oder FIN; Vertragsart (Leasing, Miete, Finanzierung, Versicherung, Wartung, Sonstiges); Vertragspartner; Vertragsnummer; Beginn; Ende; Kündigungsfrist (Monate); km-Kontingent; km bei Übernahme; Monatsrate; Nachweis; Bemerkung. Datum als TT.MM.JJJJ oder JJJJ-MM-TT, Zahlen z. B. 1.099,90 bzw. 1099.90 oder 120000. Zuerst Vorschau – vorhandene Verträge bleiben unverändert.', ct_import_src: 'Nachweis für Zeilen ohne eigenen Nachweis (z. B. Ordner/Datei)', ct_known: 'bereits erfasst' });
Object.assign(STRINGS.uk, { ct_import: 'Імпорт договорів (CSV)', ct_import_hint: 'Заголовки стовпців – німецькою, як в експорті: Kennzeichen (номерний знак) або FIN (VIN); Vertragsart (Leasing, Miete, Finanzierung, Versicherung, Wartung, Sonstiges); Vertragspartner (контрагент); Vertragsnummer (номер договору); Beginn (початок); Ende (кінець); Kündigungsfrist (Monate) (строк розірвання, місяців); km-Kontingent (ліміт км); km bei Übernahme (км при передачі); Monatsrate (щомісячний платіж, нетто); Nachweis (підтвердження); Bemerkung (примітка). Дата як ДД.ММ.РРРР або РРРР-ММ-ДД, числа без роздільника тисяч (напр. 1099.90 або 1099,90; 120000). Спочатку попередній перегляд – наявні договори не змінюються.', ct_import_src: 'Підтвердження для рядків без власного (напр. папка/файл)', ct_known: 'вже додано' });
Object.assign(STRINGS.en, { ct_import: 'Import contracts (CSV)', ct_import_hint: 'Column headers in German, as in the export: Kennzeichen (plate) or FIN (VIN); Vertragsart (Leasing, Miete, Finanzierung, Versicherung, Wartung, Sonstiges); Vertragspartner (partner); Vertragsnummer (contract number); Beginn (start); Ende (end); Kündigungsfrist (Monate) (notice period, months); km-Kontingent (mileage allowance); km bei Übernahme (km at handover); Monatsrate (monthly rate, net); Nachweis (evidence); Bemerkung (note). Dates as DD.MM.YYYY or YYYY-MM-DD, numbers without thousands separator (e.g. 1099.90; 120000 – not 120,000). Preview first – existing contracts stay unchanged.', ct_import_src: 'Evidence for rows without their own (e.g. folder/file)', ct_known: 'already recorded' });
