Object.assign(STRINGS.de, { asev_act: 'Kritisch + Handeln', todo_vfind_crit: 'Fahrzeuge mit kritischen Agentenbefunden', show_in_vlist: 'In der Fahrzeugliste anzeigen', af_filter: 'Auswahl', af_shown: 'Befunde angezeigt: {n} von {m}', vsort_findings: 'Agentenbefunde (meiste kritische zuerst)', av_with_findings: 'Mit Agentenbefunden', av_with_findings_crit: 'Mit kritischen Agentenbefunden', vfind_n: '{n}× Agentenbefund offen', vfind_crit: '{n} kritisch', import_recalls: 'Rückrufe importieren (Hersteller-/KBA-Liste)', import_recalls_hint: 'CSV mit Kennzeichen oder FIN, Referenz (Rückrufnummer laut Schreiben), optional Frist (nur wenn im Schreiben genannt) und Bemerkung. Je Fahrzeug und Referenz wird ein Rückruf angelegt; vorhandene Rückrufe werden nicht doppelt angelegt, eine vorhandene Frist wird nie überschrieben. Zuerst Vorschau, dann Übernehmen.', recall_ref: 'Referenz', av_recall_open: 'Rückruf offen', recall_open_n: '{n}× Rückruf offen', av_maint_overdue: 'Prüfung/Wartung überfällig', vsort_km_due: 'km-Fälligkeit (wenigste Rest-km zuerst)', sort_by: 'Sortieren', vsort_plate: 'Kennzeichen', vsort_next_due: 'nächste Prüfung zuerst', vsort_check_oldest: 'Abfahrtskontrolle am längsten her', vsort_km_desc: 'km-Stand (höchster zuerst)' });
