export const AUDIT_ACTION_CODES = Object.keys(AUDIT_ACTIONS);
export function auditActionLabel(lang, code) {
  const e = AUDIT_ACTIONS[code];
  return e ? e[{ de: 0, uk: 1, en: 2 }[lang] ?? 0] : null;
}

