Object.assign(STRINGS.de, { rcpt_title: "Wareneingang", rcpt_hint: "Eine Lieferung mit mehreren Positionen in einem Schritt buchen: Lieferant und Lieferschein einmal angeben, je Position Artikel, Menge und – falls bekannt – Einkaufspreis (wird zum Artikelpreis). Alle Positionen werden gemeinsam gebucht oder gar nicht; ein vorhandener Bestellvermerk endet. Neue Artikel zuerst im Lager anlegen.", rcpt_lines: "Positionen", rcpt_add: "Position hinzufügen", rcpt_remove: "Position entfernen", rcpt_book: "Wareneingang buchen", rcpt_count: "Positionen mit Artikel: {n}", rcpt_max: "Höchstens 50 Positionen je Wareneingang.", rcpt_need_line: "Mindestens eine Position angeben.", rcpt_need_item: "Bitte einen Artikel wählen.", rcpt_need_qty: "Bitte die Menge angeben.", rcpt_twice: "Ein Artikel steht mehrfach im Wareneingang – Mengen bitte zusammenfassen.", rcpt_done: "Wareneingang gebucht – Positionen: {n}", rcpt_no_items: "Noch keine aktiven Artikel im Lager – bitte zuerst Artikel anlegen." });
Object.assign(STRINGS.uk, { rcpt_title: "Надходження товару", rcpt_hint: "Провести поставку з кількома позиціями за один крок: постачальника й накладну вказати один раз, для кожної позиції – артикул, кількість і, якщо відомо, закупівельну ціну (стає ціною артикула). Усі позиції проводяться разом або жодна; наявна позначка замовлення завершується. Нові артикули спершу створіть на складі.", rcpt_lines: "Позиції", rcpt_add: "Додати позицію", rcpt_remove: "Видалити позицію", rcpt_book: "Провести надходження", rcpt_count: "Позицій з артикулом: {n}", rcpt_max: "Не більше 50 позицій на одне надходження.", rcpt_need_line: "Вкажіть щонайменше одну позицію.", rcpt_need_item: "Виберіть артикул.", rcpt_need_qty: "Вкажіть кількість.", rcpt_twice: "Артикул кілька разів у надходженні – об’єднайте кількості.", rcpt_done: "Надходження проведено – позицій: {n}", rcpt_no_items: "На складі ще немає активних артикулів – спершу створіть артикули." });
Object.assign(STRINGS.en, { rcpt_title: "Goods receipt", rcpt_hint: "Post a delivery with several lines in one step: enter supplier and delivery note once, and for each line the item, quantity and – if known – purchase price (becomes the item price). All lines are posted together or not at all; an existing order note ends. Create new items in the stock first.", rcpt_lines: "Lines", rcpt_add: "Add line", rcpt_remove: "Remove line", rcpt_book: "Post goods receipt", rcpt_count: "Lines with item: {n}", rcpt_max: "At most 50 lines per goods receipt.", rcpt_need_line: "Please enter at least one line.", rcpt_need_item: "Please choose an item.", rcpt_need_qty: "Please enter the quantity.", rcpt_twice: "An item appears more than once in the goods receipt – please combine the quantities.", rcpt_done: "Goods receipt posted – lines: {n}", rcpt_no_items: "No active items in stock yet – please create items first." });
